<?php
namespace ProjectPress\Includes\Project\Delivery;
use ProjectPress\Includes\Functions\Helpers\DBHelper;
if(!defined('ABSPATH')){exit;}final class DeliveryRepository{private string$table;private string$class;public function __construct(string$type){$map=array('sprint'=>array('sprints',Sprint::class),'release'=>array('releases',Release::class),'deployment'=>array('deployments',Deployment::class),'environment'=>array('environments',Environment::class));if(!isset($map[$type]))throw new \InvalidArgumentException('Invalid delivery type.');$this->table=$map[$type][0];$this->class=$map[$type][1];}public function find(int$id){$row=DBHelper::get_by_id($this->table,absint($id));return is_array($row)?new $this->class($row):null;}public function for_project(int$id):array{$class=$this->class;return array_map(static fn(array$row)=>new $class($row),DBHelper::get_all($this->table,array('project_id'=>absint($id)),'*','created_at DESC'));}public function create(int$id,array$data){$now=current_time('mysql',true);$record=DBHelper::insert($this->table,array_merge($data,array('project_id'=>absint($id),'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_by'=>get_current_user_id(),'updated_at'=>$now)));return false===$record?false:$this->find((int)$record);}public function update($record,array$data):bool{return DBHelper::update($this->table,array_merge($data,array('updated_by'=>get_current_user_id(),'updated_at'=>current_time('mysql',true))),array('id'=>$record->get_id(),'project_id'=>$record->get_project_id()));}public function delete($record):bool{return DBHelper::delete($this->table,array('id'=>$record->get_id(),'project_id'=>$record->get_project_id()));}}
